/// Palette letter -> RGBA (non-premultiplied).
pub fn color(ch: u8) [4]u8 {
    return switch (ch) {
        '.' => .{ 0, 0, 0, 0 },
        'K' => .{ 26, 26, 30, 255 },
        'W' => .{ 245, 245, 245, 255 },
        'w' => .{ 200, 206, 216, 255 },
        'X' => .{ 10, 10, 12, 255 },
        'Y' => .{ 255, 210, 63, 255 },
        'y' => .{ 120, 255, 190, 85 },
        'O' => .{ 255, 140, 42, 255 },
        'R' => .{ 232, 68, 58, 255 },
        'r' => .{ 168, 42, 36, 255 },
        'P' => .{ 255, 126, 182, 255 },
        'G' => .{ 95, 211, 95, 255 },
        'g' => .{ 47, 143, 63, 255 },
        'B' => .{ 58, 123, 213, 255 },
        'b' => .{ 31, 74, 138, 255 },
        'L' => .{ 143, 211, 255, 255 },
        'S' => .{ 184, 188, 196, 255 },
        'H' => .{ 107, 111, 120, 255 },
        'N' => .{ 138, 90, 43, 255 },
        'T' => .{ 224, 176, 114, 255 },
        'V' => .{ 155, 92, 240, 255 },
        'v' => .{ 90, 47, 160, 255 },
        else => .{ 0, 0, 0, 0 },
    };
}

